if (n == 0) return 1.0;

const double nD = static_cast<double>(n);
const double absAlpha = std::abs(alpha);

// Threshold for switching to Stirling approximation
// When n! would overflow double (~170!) or when n is large enough
if (n > 100) {
    // Stirling approximation: ln(n!) ≈ n ln n - n + 0.5 ln(2πn)
    const double lnNFactorial = nD * std::log(nD) - nD + 0.5 * std::log(2.0 * M_PI * nD);
    const double lnResult = nD * std::log(absAlpha) - 0.5 * lnNFactorial;
    return std::exp(lnResult) * std::pow(alpha / absAlpha, n);
} else {
    // Direct computation for small n
    dcomp result = 1.0;
    for (unsigned long k = 1; k <= n; ++k) {
        result *= alpha / std::sqrt(static_cast<double>(k));
    }
    return result;
}

